// range를 specifyRangeA1로 바꾸면서 매 폴링마다 시트 전체를 읽으므로(firstDataRow 미지원),
// '가져온 행 수'로 lastRowProcessed를 계산하던 이전 방식은 더 이상 맞지 않는다.
// 대신 이번 실행에서 실제로 '빈 행 제거'를 통과해 처리된 행들의 row_number(_1) 최댓값으로 갱신한다.
const staticData = $getWorkflowStaticData('global');
const processedRowNumbers = $('빈 행 제거').all()
  .map((item) => Number(item.json.row_number_1))
  .filter((n) => Number.isFinite(n));
const previous = Number(staticData.lastRowProcessed) || 1;
if (processedRowNumbers.length > 0) {
  staticData.lastRowProcessed = Math.max(previous, ...processedRowNumbers);
}
return [{ json: { status: "success", lastRowProcessed: staticData.lastRowProcessed } }];

const staticData = $getWorkflowStaticData('global');
const currentBatchMaxId = $('더 처리할 글 있는지 확인').first().json.currentBatchMaxId;
if (currentBatchMaxId > (staticData.lastArticleId || 0)) {
  staticData.lastArticleId = currentBatchMaxId;
}
return $input.all();

const staticData = $getWorkflowStaticData('global');
const processedUids = staticData.processedEmailUids || [];
const uid = $json.attributes?.uid || $json.headers?.['message-id'];
const isProcessed = uid ? processedUids.includes(String(uid)) : false;
return [{ json: { ...$json, isProcessed } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedEmailUids) {
  staticData.processedEmailUids = [];
}
const uid = $('데이터 파싱1').item.json.attributes?.uid || $('데이터 파싱1').item.json.headers?.['message-id'];
if (uid && !staticData.processedEmailUids.includes(String(uid))) {
  staticData.processedEmailUids.push(String(uid));
}
return $input.all();

const staticData = $getWorkflowStaticData('global');
staticData.processedEmailUids = [];
return [{ json: { status: "success", cleared: true } }];

const data = $input.item.json;

const clean = (v) => (v === undefined || v === null) ? null : String(v).trim();
const normalizeKey = (v) => String(v || "")
  .replace(new RegExp("[\\u200B-\\u200D\\uFEFF]", "g"), "")
  .replace(/[\r\n]+/g, " ")
  .replace(/\s+/g, " ")
  .trim();
const parseTime = (v) => v && !isNaN(v) ? new Date((v - 25569) * 86400000 - 32400000).toISOString().replace("Z", "+09:00") : v || null;
const normalizeUserCode = (v) => {
  const value = clean(v);
  if (!value) return null;
  if (/^[-+]?\d+(\.\d+)?e[-+]?\d+$/i.test(value) || /^\d+\.0+$/.test(value)) {
    const numeric = Number(value);
    return Number.isFinite(numeric) ? numeric.toFixed(0) : value;
  }
  return value;
};

// 앞단 "분기별 읽기 병합"(Merge, combine by position, resolveClash=addSuffix)이
// 입력1(A:H)/입력2(I:Q)/입력3(R:X)의 모든 필드 키 뒤에 각각 _1/_2/_3을 붙여 하나의 아이템으로 합쳐준다.
// 따라서 각 분기 헤더는 접미사까지 포함해서 조회해야 한다.
function field(header, suffix) {
  const targetKey = normalizeKey(header + "_" + suffix);
  const keys = Object.keys(data || {});
  const matchedKey = keys.find((key) => normalizeKey(key) === targetKey);
  return matchedKey ? clean(data[matchedKey]) : null;
}

// 유저코드/연락처/이메일/답변경로/문의내용 질문은 문의 항목(type)에 따라
// C/I/R, D/J/S, F/L/U, E/K/T, G/P/W 열에 각각 동일한 질문으로 3번 반복되어 있다.
// "문의 항목" 텍스트값을 기준으로 분기를 고르는 대신, 세 분기 중 실제로 값이 채워진 열을 그대로 사용한다.
function pick(header) {
  return field(header, "1") || field(header, "2") || field(header, "3");
}

const H = {
  timestamp: "타임스탬프",
  rowNumber: "row_number",
  type: "문의 항목을 선택해주세요.",
  userCode: "런데이 유저코드를 입력해주세요.",
  contact: "연락처를 입력해주세요.",
  replyType: "답변받고 싶은 경로를 선택해주세요.",
  replyEmail: "위 항목에 '이메일' 선택 시 이메일주소를 입력해주세요.",
  category: "문의 카테고리를 선택해주세요",
  content: "문의 상세내용을 전달해주세요.",
  appVersion: "런데이 앱 버전을 알려주세요.",
  model: "휴대폰 기종을 알려주세요.",
  osVersion: "소프트웨어 버전을 알려주세요."
};

const type = field(H.type, "1");

const userCode = normalizeUserCode(pick(H.userCode));
const contact = pick(H.contact);
const replyType = pick(H.replyType);
const replyEmail = pick(H.replyEmail);
const content = pick(H.content);

// 카테고리(V열)는 챌린지 분기(3)에만, 앱버전/기종/OS버전은 버그 분기(2)에만 존재하는 단독 필드라
// 굳이 세 분기를 다 뒤질 필요 없이 해당 분기에서만 읽으면 되고, 값이 없으면 자연히 null이 된다.
const category = field(H.category, "3");
const appVersion = field(H.appVersion, "2");
const model = field(H.model, "2");
const osVersion = field(H.osVersion, "2");

const actualRowNumber = Number(field(H.rowNumber, "1"));
const timestamp = field(H.timestamp, "1");

return {
  json: {
    timestamp: parseTime(timestamp),
    userCode,
    channelMetadata: {
      type,
      category,
      rowNumber: actualRowNumber,
      contact,
      reply: (replyType || replyEmail) ? {
        type: replyType,
        email: replyEmail
      } : null
    },
    content,
    deviceInfo: (appVersion || model || osVersion) ? {
      appVersion,
      model,
      osVersion
    } : null
  }
};

const staticData = $getWorkflowStaticData('global');
// 이전 기록이 없으면 0으로 시작
return [{ json: { lastArticleId: staticData.lastArticleId || 0 } }];

const targetMenuIds = [49, 36, 37, 42, 12];
const initialLastId = $('기존 처리 정보 가져오기').first().json.lastArticleId;

// 이전 노드(게시글 조회)에서 에러가 발생했는지 확인
if ($input.item.json.error) {
  throw new Error(`[게시글 조회 실패] ${$input.item.json.error.message}`);
}

const articles = $input.item.json.message?.result?.articleList || [];

// 1. 수집 대상 게시판 중 과거 번호보다 '큰' 번호를 가진 새 글만 필터링
const newArticles = articles.filter(a => a.articleId > initialLastId && targetMenuIds.includes(a.menuId));

// 2. 전체 글 기준 최대 글 번호를 트래킹하여 다음 증분 수집 시 중복 조회 방지
const currentBatchMaxId = articles.length > 0 ? Math.max(...articles.map(a => a.articleId)) : initialLastId;

// 3. 카페 전체에 아직 처리되지 않은 새 글이 더 있는지 여부로 페이징 지속 판단
const shouldContinue = articles.some(a => a.articleId > initialLastId);

return [{  json: {
    newArticles: newArticles,
    currentBatchMaxId: currentBatchMaxId,
    shouldContinue: shouldContinue,
    count: newArticles.length
  }
}];

const staticData = $getWorkflowStaticData('global');

// 루프 첫 바퀴에서 뽑아뒀던 가장 큰 글 번호를 가져옵니다.
// 필터링을 수행한 노드 이름을 사용합니다.
const firstLoopData = $items("더 처리할 글 있는지 확인", 0, 0)[0].json;

if (firstLoopData.currentBatchMaxId > (staticData.lastArticleId || 0)) {
    staticData.lastArticleId = firstLoopData.currentBatchMaxId;
}

return [{ json: { status: "증분 수집 완료", updatedId: staticData.lastArticleId } }];

// If 노드를 통과한 배열(newArticles)을 가져옵니다.
const newArticles = $input.first().json.newArticles || [];

// 배열의 각 항목을 n8n이 인식하는 개별 아이템 구조({json: {...}})로 매핑하여 통째로 리턴합니다.
return newArticles.map(article => {
  return {
    json: article
  };
});

const inputData = $input.item.json;
const articleId = inputData.articleId;

const matchedItem = $('데이터 파싱').all(0, $runIndex).find(item => String(item.json.articleId) === String(articleId));
const rawData = matchedItem ? matchedItem.json : {};

const images = inputData.images || [];
const objectKeys = images.map(img => img.objectName).filter(Boolean);

return {
  json: {
    workflow_name: "csDataIntegration",
    payload: {
      channel: "NAVER_CAFE",
      items: [
        {
          timestamp: rawData.timestamp,
          userCode: null,
          content: rawData.content,
          imageUrls: objectKeys,
          channelMetadata: {
            cafeId: rawData.cafeId,
            articleId: rawData.articleId,
            menu: {
              id: rawData.menuId,
              name: rawData.menuName
            },
            articleUrl: `https://m.cafe.naver.com/ca-fe/web/cafes/${rawData.cafeId}/articles/${rawData.articleId}`,
            writer: {
              id: rawData.writerId,
              nickname: rawData.writerNickname
            },
            metrics: {
              readCount: rawData.readCount,
              commentCount: rawData.commentCount,
              likeCount: rawData.likeCount
            },
            imageUrls: objectKeys,
            comments: rawData.comments || []
          }
        }
      ]
    }
  }
};

const rawData = $input.item.json;

return {
  json: {
    workflow_name: "csDataIntegration",
    payload: {
      channel: "NAVER_CAFE",
      items: [
        {
          timestamp: rawData.timestamp,
          userCode: null,
          content: rawData.content,
          imageUrls: [],
          channelMetadata: {
            cafeId: rawData.cafeId,
            articleId: rawData.articleId,
            menu: {
              id: rawData.menuId,
              name: rawData.menuName
            },
            articleUrl: `https://m.cafe.naver.com/ca-fe/web/cafes/${rawData.cafeId}/articles/${rawData.articleId}`,
            writer: {
              id: rawData.writerId,
              nickname: rawData.writerNickname
            },
            metrics: {
              readCount: rawData.readCount,
              commentCount: rawData.commentCount,
              likeCount: rawData.likeCount
            },
            imageUrls: [],
            comments: rawData.comments || []
          }
        }
      ]
    }
  }
};

// n8n 내부에 저장된 전역 변수(Static Data)를 불러옵니다.
const staticData = $getWorkflowStaticData('global');

const lastRowProcessed = staticData.lastRowProcessed || 1;

return {
  lastRowProcessed: lastRowProcessed
};

const allPresignedItems = $input.all();
const allArticles = $('데이터 파싱').all(0, $runIndex);
const pairedItems = [];

for (const item of allPresignedItems) {
  const urls = item.json.urls || [];
  if (urls.length === 0) continue;

  const firstObjectName = urls[0].objectName || "";
  const parts = firstObjectName.split('/');
  if (parts.length < 2) continue;
  const idParts = parts[1].split('_');
  const cafeId = idParts[0];
  const articleId = idParts[1];

  const matchedArticle = allArticles.find(art => String(art.json.articleId) === String(articleId));
  const originalUrls = matchedArticle ? (matchedArticle.json.originalImageUrls || []) : [];

  urls.forEach((urlItem, index) => {
    pairedItems.push({
      json: {
        cafeId: cafeId,
        articleId: articleId,
        originalImageUrl: originalUrls[index] || "",
        objectName: urlItem.objectName,
        uploadUrl: urlItem.uploadUrl,
        downloadUrl: urlItem.downloadUrl
      }
    });
  });
}

return pairedItems;

const items = $input.all();

return items
  .filter((item) => item.binary?.data && item.json?.uploadUrl)
  .map((item) => ({
    json: item.json,
    binary: item.binary,
    pairedItem: item.pairedItem
  }));

const result = $input.item.json?.result || {};
const detail = result.article || {};
const listData = $('게시글 상세 조회를 위한 데이터 파싱').item?.json || {};

function stripAndCleanHtml(html) {
  if (!html) return "";
  let text = html.replace(/\[\[\[.*?\]\]\]/g, "");
  text = text.replace(/<br\s*[\/]?>/gi, "\n");
  text = text.replace(/<\/p>|<\/div>|<\/h[1-6]>/gi, "\n");
  text = text.replace(/<[^>]*>?/gm, "");
  text = text.replace(/&nbsp;/gi, " ");
  text = text.replace(/&[a-z]+;/gi, "");
  text = text.replace(/[ \t]+/g, " ");
  text = text.replace(/\n\s*\n+/g, "\n\n");
  return text.trim();
}

function normalizeImageUrl(url) {
  if (typeof url !== "string") return url;
  let cleanUrl = url
    .replace(/&amp;/g, '&')
    .replace(/&#x3D;/g, '=')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/%22/g, '')
    .replace(/"/g, '')
    .replace(/src==/g, 'src=')
    .replace(/type==/g, 'type=');
  return cleanUrl.replace("://cafepthumb-phinf.pstatic.net", "://cafeptthumb-phinf.pstatic.net");
}

function extractCommentImages(comment) {
  const images = [];
  const addUrl = (value) => {
    const normalized = normalizeImageUrl(value);
    if (normalized && !images.includes(normalized)) {
      images.push(normalized);
    }
  };

  if (comment.image?.url) addUrl(comment.image.url);
  if (comment.sticker?.url) addUrl(comment.sticker.url);
  if (Array.isArray(comment.imageList)) {
    comment.imageList.forEach((image) => addUrl(image?.url || image?.src));
  }

  const html = comment.contentHtml || comment.content || "";
  const imgRegex = /<img[^>]+src=["']([^"']+)["']/g;
  let match;
  while ((match = imgRegex.exec(html)) !== null) {
    addUrl(match[1]);
  }

  return images;
}

const content = stripAndCleanHtml(detail.contentHtml || detail.content || "");
const timestamp = detail.writeDate ? new Date(detail.writeDate).toISOString() : new Date().toISOString();

const originalImageUrls = [];

// 1. Extract from official imageList
if (detail.imageList && Array.isArray(detail.imageList)) {
  detail.imageList.forEach(img => {
    if (img.url) {
      originalImageUrls.push(img.url);
    }
  });
}

// 2. Parse inline <img> tags from contentHtml or content
const htmlContent = detail.contentHtml || detail.content || "";
const imgRegex = /<img[^>]+src=["']([^"']+)["']/g;
let match;
while ((match = imgRegex.exec(htmlContent)) !== null) {
  const url = match[1];
  if (!originalImageUrls.includes(url)) {
    originalImageUrls.push(url);
  }
}

// 3. Fallback to representImage if originalImageUrls is still empty
if (originalImageUrls.length === 0 && detail.representImage && detail.representImage.url) {
  originalImageUrls.push(detail.representImage.url);
}

const normalizedImageUrls = originalImageUrls.map(normalizeImageUrl);

const clubId = listData.cafeId || listData.clubId || "unknown";
const articleId = listData.articleId || detail.articleId || "unknown";

const objectNames = normalizedImageUrls.map((url, index) => {
  return "naver-cafe/" + clubId + "_" + articleId + "/image_" + index + ".jpg";
});

const rawComments = result.comments?.items || result.comments || detail.comments?.items || [];
const parentWriterNickname = listData.writerNickname || (detail.writer ? detail.writer.nickname : null);
const comments = Array.isArray(rawComments)
  ? rawComments.map((comment) => {
      const writer = comment.writer || {};
      const writerNickname = writer.nickname || writer.nick || writer.name || "";
      const writerId = writer.id || writer.memberId || writer.maskedMemberId || "";
      const writeDateValue = comment.updateDate || comment.writeDate || comment.createdAt || null;
      const writeDate = typeof writeDateValue === "number"
        ? new Date(writeDateValue).toISOString()
        : (writeDateValue ? new Date(writeDateValue).toISOString() : new Date().toISOString());
      const commentId = comment.id || comment.commentId || null;
      const commentContent = stripAndCleanHtml(comment.contentHtml || comment.content || "");
      const isOperator = parentWriterNickname ? parentWriterNickname !== writerNickname : false;

      return {
        commentId,
        content: commentContent,
        writer: {
          id: writerId,
          nickname: writerNickname
        },
        writeDate,
        isOperator,
        imageUrls: extractCommentImages(comment)
      };
    })
  : [];

return {
  cafeId: clubId,
  articleId: articleId,
  menuId: listData.menuId,
  menuName: listData.menuName,
  writerId: listData.maskedMemberId || (detail.writer ? detail.writer.id : null),
  writerNickname: listData.writerNickname || (detail.writer ? detail.writer.nickname : null),
  readCount: detail.readCount || 0,
  commentCount: detail.commentCount || listData.commentCount || comments.length,
  likeCount: detail.likeItCount || 0,
  content: content,
  timestamp: timestamp,
  originalImageUrls: normalizedImageUrls,
  objectNames: objectNames,
  comments
};

const sourceItem = $('데이터 파싱1').itemMatching(0);
const originalUrls = sourceItem.json.originalImageUrls || [];
const sourceBinary = sourceItem.binary || {};
const presignedUrls = $input.first().json.urls || [];
const uploadContentType = sourceItem.json.imageContentType || "application/octet-stream";

return presignedUrls.map((item, index) => {
  const key = originalUrls[index];
  const binary = key ? sourceBinary[key] : null;

  if (!binary || !binary.data) {
    throw new Error("Email image binary is missing before upload. key=" + (key || "") + ", objectName=" + (item.objectName || ""));
  }

  return {
    json: {
      originalUrl: key,
      objectName: item.objectName,
      uploadUrl: item.uploadUrl,
      downloadUrl: item.downloadUrl,
      contentType: uploadContentType
    },
    binary: { data: binary },
    pairedItem: { item: 0 }
  };
});

return {
  json: $json,
  binary: $binary
};

const rawEmail = $input.item.json;
const metadata = rawEmail.metadata || {};
const headers = rawEmail.headers || {};
const attributes = rawEmail.attributes || {};

function readHeader(name) {
  const value = metadata[name] ?? headers[name] ?? headers[name.toLowerCase()];
  if (Array.isArray(value)) return value[0] || "";
  if (!value) return "";
  const raw = String(value);
  const prefix = name + ":";
  return raw.toLowerCase().startsWith(prefix.toLowerCase())
    ? raw.slice(prefix.length).trim()
    : raw.trim();
}

function normalizeMessageId(value) {
  if (!value) return "";
  const first = Array.isArray(value) ? value[0] : value;
  return String(first).replace(/[<>]/g, "").trim();
}

function normalizeReferences(value) {
  if (!value) return "";
  const raw = Array.isArray(value) ? value.join(" ") : String(value);
  return raw
    .split(/\s+/)
    .map(normalizeMessageId)
    .filter(Boolean)
    .join(" ");
}

function formatAddress(value) {
  if (!value) return "";
  if (typeof value === "string") return value;
  if (value.text) return value.text;
  if (Array.isArray(value.value)) {
    return value.value
      .map((entry) => entry.name ? entry.name + " <" + entry.address + ">" : entry.address)
      .filter(Boolean)
      .join(", ");
  }
  return String(value);
}

function stripAndCleanHtml(html) {
  if (!html) return "";
  let text = html.replace(/<br\s*[\/]?>/gi, "\n");
  text = text.replace(/<\/p>|<\/div>|<\/h[1-6]>/gi, "\n");
  text = text.replace(/<[^>]*>?/gm, "");
  text = text.replace(/&nbsp;/gi, " ");
  text = text.replace(/&[a-z]+;/gi, "");
  text = text.replace(/[ \t]+/g, " ");
  text = text.replace(/\n\s*\n+/g, "\n\n");
  return text.trim();
}

const messageId = normalizeMessageId(readHeader("message-id"));
const inReplyTo = normalizeMessageId(readHeader("in-reply-to"));
const references = normalizeReferences(readHeader("references"));
const uid = attributes.uid || null;

if (!uid && !messageId) {
  throw new Error("Email identity is missing. Expected attributes.uid or message-id from EmailReadImap.");
}

let timestamp = new Date().toISOString();
if (rawEmail.date) {
  const parsed = new Date(rawEmail.date);
  if (!Number.isNaN(parsed.getTime())) {
    timestamp = parsed.toISOString();
  }
}

const plainContent = typeof rawEmail.text === "string"
  ? rawEmail.text.trim()
  : (typeof rawEmail.textPlain === "string" ? rawEmail.textPlain.trim() : "");
const htmlContent = stripAndCleanHtml(rawEmail.html || rawEmail.textHtml || "");
const content = plainContent || htmlContent;

const originalImageUrls = [];
const objectNames = [];
let imageContentType = "application/octet-stream";
const binaryData = $input.item.binary;
if (typeof binaryData === "object" && binaryData !== null) {
  const datePart = timestamp.substring(0, 10).replace(/-/g, "");
  const uniqueSource = messageId || "uid_" + uid;
  const uniqueId = uniqueSource.replace(/[^a-zA-Z0-9_-]/g, "_");

  Object.keys(binaryData).forEach((key, index) => {
    const file = binaryData[key];
    if (file && file.mimeType && file.mimeType.startsWith("image/")) {
      if (originalImageUrls.length === 0) {
        imageContentType = file.mimeType;
      }
      const ext = (file.fileExtension || "jpg").toLowerCase();
      const objectName = "email/" + datePart + "/" + uniqueId + "/image_" + index + "." + ext;
      originalImageUrls.push(key);
      objectNames.push(objectName);
    }
  });
}

if (!content && originalImageUrls.length === 0) {
  throw new Error("Email has neither text content nor image binary. Check EmailReadImap resolved output. uid=" + (uid || "") + ", messageId=" + messageId);
}

const subject = rawEmail.subject || "";
const combinedText = subject + " " + content;
const userCodeMatch = combinedText.match(/\b\d{4}[ \t]?\d{4}[ \t]?\d{4}\b/);
const userCode = userCodeMatch ? userCodeMatch[0].replace(/[ \t]/g, "") : null;
return {
  json: {
    from: formatAddress(rawEmail.from),
    to: formatAddress(rawEmail.to),
    subject,
    date: rawEmail.date || "",
    headers: {
      "message-id": messageId,
      "in-reply-to": inReplyTo,
      "references": references
    },
    attributes: { uid },
    userCode,
    content,
    timestamp,
    originalImageUrls,
    objectNames,
    imageContentType
  },
  binary: $input.item.binary
};

const rawData = $('데이터 파싱1').item.json;

let objectKeys = [];
if (rawData.originalImageUrls && rawData.originalImageUrls.length > 0) {
  try {
    const allUploaded = $('이메일 이미지 업로드 완료 정보').all()
      .map(item => item.json.objectName)
      .filter(Boolean);
    objectKeys = allUploaded.filter(name => rawData.objectNames.includes(name));
  } catch (error) {
    objectKeys = [];
  }
}

return {
  json: {
    workflow_name: "csDataIntegration",
    payload: {
      channel: "EMAIL",
      items: [
        {
          timestamp: rawData.timestamp,
          userCode: rawData.userCode,
          content: rawData.content,
          imageUrls: objectKeys,
          channelMetadata: {
            from: rawData.from,
            to: rawData.to,
            subject: rawData.subject,
            date: rawData.date,
            headers: rawData.headers,
            attributes: rawData.attributes,
            articleUrl: rawData.articleUrl
          }
        }
      ]
    }
  }
};

const allImages = $input.all();
const allPaired = $('이미지 다운로드 성공 필터').all(0, $runIndex);

return allImages.map((item, index) => {
  const paired = allPaired[index] ? allPaired[index].json : {};
  return {
    json: {
      cafeId: paired.cafeId,
      articleId: paired.articleId,
      originalImageUrl: paired.originalImageUrl || "",
      objectName: paired.objectName || "",
      downloadUrl: paired.downloadUrl || ""
    }
  };
});

const uploadedItems = $input.all();
const parsedArticles = $('데이터 파싱').all(0, $runIndex);
const groups = {};

for (const article of parsedArticles) {
  const data = article.json || {};
  if (!data.articleId || !(data.originalImageUrls || []).length) continue;

  groups[String(data.articleId)] = {
    cafeId: data.cafeId,
    articleId: String(data.articleId),
    images: []
  };
}

for (const item of uploadedItems) {
  const data = item.json || {};
  const articleId = data.articleId ? String(data.articleId) : null;
  if (!articleId) continue;

  if (!groups[articleId]) {
    groups[articleId] = {
      cafeId: data.cafeId,
      articleId,
      images: []
    };
  }

  if (data.objectName) {
    groups[articleId].images.push({
      originalUrl: data.originalImageUrl || "",
      objectName: data.objectName || "",
      downloadUrl: data.downloadUrl || ""
    });
  }
}

return Object.values(groups).map(group => ({ json: group }));

const uploaded = $('이미지 정보 페어링1').item.json;

return {
  json: {
    originalUrl: uploaded.originalUrl,
    objectName: uploaded.objectName,
    downloadUrl: uploaded.downloadUrl
  }
};

